#!/usr/bin/env bash
# Applies app-specific settings to the android/ folder generated by `flutter create`.
set -euo pipefail
cd "$(dirname "$0")/.."
M=android/app/src/main/AndroidManifest.xml

# Network (ML Kit model download, live sync with teacher server on local Wi-Fi)
grep -q 'android.permission.INTERNET' "$M" || \
  sed -i 's#<application#<uses-permission android:name="android.permission.INTERNET"/>\n    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE"/>\n    <application#' "$M"
grep -q 'usesCleartextTraffic' "$M" || \
  sed -i 's#<application#<application android:usesCleartextTraffic="true"#' "$M"
# In-app updates: download the new APK and hand it to the system installer (FileProvider → cache/updates/)
grep -q 'REQUEST_INSTALL_PACKAGES' "$M" || \
  sed -i 's#<application#<uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"/>\n    <application#' "$M"
# once the app has installed itself, later updates may go through without the extra confirm (Android 12+)
grep -q 'UPDATE_PACKAGES_WITHOUT_USER_ACTION' "$M" || \
  sed -i 's#<application#<uses-permission android:name="android.permission.UPDATE_PACKAGES_WITHOUT_USER_ACTION"/>\n    <application#' "$M"
grep -q 'pulinote_update_paths' "$M" || \
  sed -i 's#</application>#    <provider android:name="androidx.core.content.FileProvider" android:authorities="${applicationId}.updates" android:exported="false" android:grantUriPermissions="true">\n            <meta-data android:name="android.support.FILE_PROVIDER_PATHS" android:resource="@xml/pulinote_update_paths"/>\n        </provider>\n    </application>#' "$M"
mkdir -p android/app/src/main/res/xml
cat > android/app/src/main/res/xml/pulinote_update_paths.xml <<'XML'
<?xml version="1.0" encoding="utf-8"?>
<paths>
    <cache-path name="updates" path="updates/" />
</paths>
XML

# 교재 파일(.pulinote): 다른 앱에서 "풀이노트로 열기" (content:// 파일, 확장자를 모르는 파일은 octet-stream)
grep -q 'application/x-gzip' "$M" || \
  sed -i '0,/<\/intent-filter>/s##</intent-filter>\n            <intent-filter>\n                <action android:name="android.intent.action.VIEW"/>\n                <category android:name="android.intent.category.DEFAULT"/>\n                <data android:scheme="content"/>\n                <data android:mimeType="application/octet-stream"/>\n                <data android:mimeType="application/gzip"/>\n                <data android:mimeType="application/x-gzip"/>\n            </intent-filter>#' "$M"
grep -q 'application/x-gzip' "$M" || { echo "ERROR: could not add the VIEW intent-filter"; exit 1; }

# App name
sed -i 's#android:label="[^"]*"#android:label="풀이노트"#' "$M"

# minSdk 24 (ML Kit + modern stylus APIs)
for G in android/app/build.gradle.kts android/app/build.gradle; do
  [ -f "$G" ] || continue
  sed -i -E 's/minSdk(Version)? *=? *flutter\.minSdkVersion/minSdk = 24/' "$G"
done

# Release: no R8 minify/shrink. R8 strips WorkManager's Room database (a dependency of ML Kit)
# and the app dies right at launch (androidx.work.impl.WorkDatabase could not be created).
for G in android/app/build.gradle.kts android/app/build.gradle; do
  [ -f "$G" ] || continue
  if [[ "$G" == *.kts ]]; then
    sed -i -E 's/^([[:space:]]*)signingConfig = signingConfigs\.getByName\("debug"\)/&\n\1isMinifyEnabled = false\n\1isShrinkResources = false/' "$G"
  else
    sed -i -E 's/^([[:space:]]*)signingConfig signingConfigs\.debug/&\n\1minifyEnabled false\n\1shrinkResources false/' "$G"
  fi
  grep -Eq 'isMinifyEnabled = false|minifyEnabled false' "$G" || { echo "ERROR: could not disable minify in $G"; cat "$G"; exit 1; }
  # FileProvider for in-app updates
  if ! grep -q 'androidx.core:core' "$G"; then
    if [[ "$G" == *.kts ]]; then
      printf '\ndependencies {\n    implementation("androidx.core:core:1.13.1")\n}\n' >> "$G"
    else
      printf "\ndependencies {\n    implementation 'androidx.core:core:1.13.1'\n}\n" >> "$G"
    fi
  fi
  echo "---- $G ----"; cat "$G"
done

# Launcher icons
if [ -d tools/icons/res ]; then
  cp -r tools/icons/res/* android/app/src/main/res/
fi

echo "---- patched manifest ----"
cat "$M"
grep -n "minSdk" android/app/build.gradle* || true

# Low-latency stylus: ask Android for unbuffered (un-batched) pen events → more points, less lag.
MA=$(find android/app/src/main -name MainActivity.kt | head -1)
if [ -n "$MA" ]; then
  PKG=$(grep -m1 '^package ' "$MA")
  cat > "$MA" <<KT
$PKG

import android.app.Activity
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.content.pm.PackageInstaller
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.provider.Settings
import android.view.MotionEvent
import androidx.core.content.ContextCompat
import androidx.core.content.FileProvider
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.ByteArrayOutputStream
import java.io.File

class MainActivity : FlutterActivity() {
    // 교재 파일 (lib/services/content_import.dart → BookFiles)
    private val pickRequest = 7301
    private var pickResult: MethodChannel.Result? = null
    private var opened: ByteArray? = null

    // In-app updates: install through a PackageInstaller session so the result (and the reason
    // when it fails) comes back to the app instead of a bare "앱이 설치되지 않음" screen.
    private val installAction get() = packageName + ".INSTALL_STATUS"
    private var updateChannel: MethodChannel? = null
    private val installReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, i: Intent) {
            val status = i.getIntExtra(PackageInstaller.EXTRA_STATUS, -999)
            if (status == PackageInstaller.STATUS_PENDING_USER_ACTION) {
                @Suppress("DEPRECATION")
                val confirm: Intent? = if (Build.VERSION.SDK_INT >= 33) i.getParcelableExtra(Intent.EXTRA_INTENT, Intent::class.java) else i.getParcelableExtra(Intent.EXTRA_INTENT)
                if (confirm != null) {
                    confirm.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                    startActivity(confirm)
                }
                return
            }
            updateChannel?.invokeMethod("installStatus", mapOf(
                "status" to status,
                "message" to (i.getStringExtra(PackageInstaller.EXTRA_STATUS_MESSAGE) ?: "")
            ))
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        ContextCompat.registerReceiver(this, installReceiver, IntentFilter(installAction), ContextCompat.RECEIVER_NOT_EXPORTED)
        takeViewIntent(intent)
    }

    override fun onDestroy() {
        try {
            unregisterReceiver(installReceiver)
        } catch (e: Exception) {
        }
        super.onDestroy()
    }

    private fun installWithSession(apk: File) {
        val installer = packageManager.packageInstaller
        val params = PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL)
        params.setAppPackageName(packageName)
        params.setSize(apk.length())
        if (Build.VERSION.SDK_INT >= 31) {
            params.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_NOT_REQUIRED)
        }
        val id = installer.createSession(params)
        installer.openSession(id).use { session ->
            apk.inputStream().use { input ->
                session.openWrite("base.apk", 0, apk.length()).use { out ->
                    input.copyTo(out)
                    session.fsync(out)
                }
            }
            val flags = PendingIntent.FLAG_UPDATE_CURRENT or (if (Build.VERSION.SDK_INT >= 31) PendingIntent.FLAG_MUTABLE else 0)
            val sender = PendingIntent.getBroadcast(this, id, Intent(installAction).setPackage(packageName), flags)
            session.commit(sender.intentSender)
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        takeViewIntent(intent)
    }

    private fun takeViewIntent(i: Intent?) {
        if (i?.action != Intent.ACTION_VIEW) return
        val uri = i.data ?: return
        try {
            opened = readUri(uri)
        } catch (e: Exception) {
            opened = null
        }
    }

    private fun readUri(uri: Uri): ByteArray? = contentResolver.openInputStream(uri)?.use { input ->
        val out = ByteArrayOutputStream()
        val buf = ByteArray(65536)
        var total = 0
        while (true) {
            val n = input.read(buf)
            if (n < 0) break
            total += n
            if (total > 64 * 1024 * 1024) throw IllegalStateException("file too large")
            out.write(buf, 0, n)
        }
        out.toByteArray()
    }

    @Deprecated("Deprecated in Java")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        if (requestCode == pickRequest) {
            val r = pickResult
            pickResult = null
            val uri = data?.data
            if (resultCode != Activity.RESULT_OK || uri == null) {
                r?.success(null)
            } else {
                try {
                    r?.success(readUri(uri))
                } catch (e: Exception) {
                    r?.error("read", e.message, null)
                }
            }
            return
        }
        @Suppress("DEPRECATION")
        super.onActivityResult(requestCode, resultCode, data)
    }

    // In-app updates (lib/services/updater.dart)
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "pulinote/files").setMethodCallHandler { call, result ->
            when (call.method) {
                "pick" -> {
                    pickResult?.success(null)
                    pickResult = result
                    val i = Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*")
                    try {
                        @Suppress("DEPRECATION")
                        startActivityForResult(i, pickRequest)
                    } catch (e: Exception) {
                        pickResult = null
                        result.error("pick", e.message, null)
                    }
                }
                "takeOpened" -> {
                    val b = opened
                    opened = null
                    result.success(b)
                }
                else -> result.notImplemented()
            }
        }
        val upd = MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "pulinote/update")
        updateChannel = upd
        upd.setMethodCallHandler { call, result ->
            try {
                when (call.method) {
                    "versionCode" -> {
                        val info = packageManager.getPackageInfo(packageName, 0)
                        @Suppress("DEPRECATION")
                        val code = if (Build.VERSION.SDK_INT >= 28) info.longVersionCode.toInt() else info.versionCode
                        result.success(code)
                    }
                    "canInstall" -> result.success(
                        if (Build.VERSION.SDK_INT >= 26) packageManager.canRequestPackageInstalls() else true
                    )
                    "openInstallSettings" -> {
                        if (Build.VERSION.SDK_INT >= 26) {
                            startActivity(Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES, Uri.parse("package:" + packageName)))
                        }
                        result.success(true)
                    }
                    "install" -> {
                        val path = call.argument<String>("path")
                        if (path == null) {
                            result.success(false)
                        } else {
                            installWithSession(File(path))
                            result.success(true)
                        }
                    }
                    "installView" -> {
                        val path = call.argument<String>("path")
                        if (path == null) {
                            result.success(false)
                        } else {
                            val uri = FileProvider.getUriForFile(this, packageName + ".updates", File(path))
                            val intent = Intent(Intent.ACTION_VIEW)
                                .setDataAndType(uri, "application/vnd.android.package-archive")
                                .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_ACTIVITY_NEW_TASK)
                            startActivity(intent)
                            result.success(true)
                        }
                    }
                    else -> result.notImplemented()
                }
            } catch (e: Exception) {
                result.error("update", e.message, null)
            }
        }
    }

    override fun dispatchTouchEvent(ev: MotionEvent): Boolean {
        val action = ev.actionMasked
        // Low latency: ask for unbuffered (un-batched) pen events, also when a palm touched first.
        if (action == MotionEvent.ACTION_DOWN || action == MotionEvent.ACTION_POINTER_DOWN) {
            val tool = ev.getToolType(ev.actionIndex)
            if (tool == MotionEvent.TOOL_TYPE_STYLUS || tool == MotionEvent.TOOL_TYPE_ERASER) {
                window.decorView.requestUnbufferedDispatch(ev)
            }
        }
        // Some firmware reports the S Pen side button as BUTTON_SECONDARY; Flutter only maps
        // BUTTON_STYLUS_PRIMARY, so translate it (the app then switches to the eraser).
        val bs = ev.buttonState
        if ((bs and MotionEvent.BUTTON_SECONDARY) != 0 && (bs and MotionEvent.BUTTON_STYLUS_PRIMARY) == 0) {
            var stylus = false
            for (i in 0 until ev.pointerCount) {
                if (ev.getToolType(i) == MotionEvent.TOOL_TYPE_STYLUS) stylus = true
            }
            if (stylus) {
                val n = ev.pointerCount
                val props = Array(n) { MotionEvent.PointerProperties() }
                val coords = Array(n) { MotionEvent.PointerCoords() }
                for (i in 0 until n) {
                    ev.getPointerProperties(i, props[i])
                    ev.getPointerCoords(i, coords[i])
                }
                val copy = MotionEvent.obtain(
                    ev.downTime, ev.eventTime, ev.action, n, props, coords, ev.metaState,
                    bs or MotionEvent.BUTTON_STYLUS_PRIMARY, ev.xPrecision, ev.yPrecision,
                    ev.deviceId, ev.edgeFlags, ev.source, ev.flags
                )
                val handled = super.dispatchTouchEvent(copy)
                copy.recycle()
                return handled
            }
        }
        return super.dispatchTouchEvent(ev)
    }
}
KT
  echo "---- MainActivity ----"; cat "$MA"
fi
